rules.logic:
element.style.backgroundColor = '#FF9900';
element.style.color = '#000000';
element.style.fontWeight = 'bold';
element.style.borderRadius = '4px 4px 0 0';
element.style.padding = '8px 16px';
element.style.boxShadow = '0 -2px 6px rgba(255, 153, 0, 0.4)';

// Add a collaborative users icon (people/users emoji as visual indicator)
const link = element.querySelector('a');
if (link) {
  // Check if we already added the icon to avoid duplicates
  if (!link.querySelector('.friends-tab-icon')) {
    const iconSpan = document.createElement('span');
    iconSpan.className = 'friends-tab-icon';
    iconSpan.textContent = '👥 ';
    iconSpan.style.marginRight = '4px';
    link.prepend(iconSpan);
  }
}
